(()=>{
const root=document.createElement('aside');root.id='lumi-guide';root.className='lumi-guide';root.setAttribute('aria-label','Lumi product guide');root.innerHTML=`<section class="lumi-panel" hidden aria-label="Guide conversation"><div class="lumi-header"><div><strong>Lumi</strong><span>Your guide · Demo</span></div><button aria-label="Minimise guide" data-lumi-close>×</button></div><div class="lumi-message" id="lumi-message" aria-live="polite"></div><div class="lumi-choices"><button data-lumi-topic="next">What should I do next?</button><button data-lumi-topic="cost">Explain the price difference</button><button data-lumi-topic="mismatch">What needs my attention?</button></div><div class="lumi-footer">Contextual tips · Live AI chat not connected</div></section><button class="lumi-launcher" aria-expanded="false" aria-controls="lumi-message"><span class="lumi-character" aria-hidden="true"><span class="lumi-eyes"><i></i><i></i></span><span class="lumi-mouth"></span><span class="lumi-cheek"></span></span><span>Ask Lumi<small>A little clarity.</small></span><span class="lumi-star" aria-hidden="true">✦</span></button>`;document.body.append(root);
const panel=root.querySelector('.lumi-panel'),launch=root.querySelector('.lumi-launcher'),message=root.querySelector('#lumi-message');
function context(){return window.getQuoteLensContext?.()||{view:'landing'}}
function explain(topic='next'){const c=context();if(c.view==='suppliers')return topic==='mismatch'?'A portfolio tells you what a supplier says they can do. Check relevant past work and the source of reviews. These profiles are illustrative or saved locally; they are not verified businesses.':topic==='cost'?'A quote is more useful when the scope is clear. Share quantity, location, dates, and must-haves, then ask for taxes, delivery, payment terms, and exclusions.':'Open a supplier’s portfolio to explore their capabilities, projects, and client remarks. If you supply services, “List your business” starts your own local profile draft.';if(c.view==='landing')return 'Start in My Tenders if you already have a purchase to plan. Explore suppliers if you first need to find the people who can deliver it. I can point you to the next step.';if(!c.hasAssessment&&['comparison','evaluation','drafts'].includes(c.view))return 'This tender has no current evaluation. Add the supplier offers and review the requirements first. The sample analysis belongs only to the sample tender.';if(topic==='cost')return 'Print & Co. is ₹31,000 with its optional sample. Studio Merch is ₹32,400, so you pay ₹1,400 extra for individual packaging. Both meet the essentials. If bulk packaging works for you, the cheaper eligible offer may be better.';if(topic==='mismatch')return 'Campus Supply misses the deadline by two days. QuickPrint also misses the material and advance-payment limits. Those red checks are mandatory failures; amber checks are optional costs or allowed compromises.';if(c.view==='requirements')return 'Tell me what success looks like, what must not change, and where you can compromise. The custom instructions field is the place for context that a standard form can’t capture.';if(c.view==='quotations')return 'Add a PDF for each supplier, then confirm the supplier name, contact and quoted amount. Files stay attached to this tender. Live extraction is not connected yet.';if(c.view==='drafts')return 'Open a draft to review its goal and edit the message. Your edits save locally. Nothing is sent from this preview.';if(c.view==='evaluation')return 'The activity log shows operational events and results. “Replay sample run” demonstrates how the feed will progress; it isn’t a live backend session.';if(c.view==='comparison')return 'Select a bar to inspect the offer. Switch between total cost and advance, then scan the requirement cards. “Include excluded offers” reveals why the lowest prices did not make the shortlist.';return 'Create a new tender or open an existing one. Each has its own requirements, documents, comparison, activity and draft emails.';}
function open(topic){panel.hidden=false;launch.setAttribute('aria-expanded','true');message.textContent=explain(topic)}
launch.addEventListener('click',()=>{if(panel.hidden)open('next');else{panel.hidden=true;launch.setAttribute('aria-expanded','false')}});
root.querySelector('[data-lumi-close]').addEventListener('click',()=>{panel.hidden=true;launch.setAttribute('aria-expanded','false');launch.focus()});
root.querySelectorAll('[data-lumi-topic]').forEach(b=>b.addEventListener('click',()=>open(b.dataset.lumiTopic)));
document.addEventListener('click',e=>{const b=e.target.closest('[data-guide]');if(b)open(b.dataset.guide)});
window.addEventListener('quotelens:view',()=>{if(!panel.hidden)message.textContent=explain('next')});
})();
